 		return NULL;
 	}
 	if (!no_block_check && gf_filter_pid_would_block(pid))
 		return NULL;

 	count = gf_fq_count(pid->filter->pcks_alloc_reservoir);
 	if (count) {
+		GF_PckQueueEnum pck_enum_state;
